with open('/app/benchmark/source_data.json', 'r') as f:
    data = json.load(f)

regions = ["North America", "Europe", "South Asia", "Sub-Saharan Africa"]

def get_dimension_data(dimension_key, region, label_key, min_label_contains, max_label_contains):
