    items = [x for x in data[dimension_key]['data'] if x['region'] == region]
    if dimension_key == 'internet_by_income_quintile':
        # Sort chronologically Q1 to Q5
        pass

    # Actually, we can just grab all values for the dots
    vals = [x['penetration'] for x in items]
    vals.sort()

    v_min, v_max = vals[0], vals[-1]

